SELECT CASE WHEN quantity >= 211 THEN 'LARGE' ELSE 'SMALL' END AS quantity_tier, store_id, SUM(quantity) AS total_quantity, MAX(quantity) AS max_quantity, ROUND(AVG(quantity), 2) AS avg_quantity, COUNT(DISTINCT product_id) AS distinct_product_ids, ROUND(AVG(quantity), 2) AS avg_quantity_2, STDDEV_SAMP(quantity) AS quantity_stddev FROM inventory GROUP BY ROLLUP (CASE WHEN quantity >= 211 THEN 'LARGE' ELSE 'SMALL' END, store_id) ORDER BY avg_quantity NULLS LAST
